import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { app } from "../src/api/routes.ts";
import { resetUsers } from "../src/auth/users.ts";
import { resetSessions } from "../src/auth/session.ts";

const call = (method: string, path: string, body?: unknown, token?: string) =>
  app({ method, path, body, headers: token ? { authorization: `Bearer ${token}` } : {} });

beforeEach(() => {
  resetUsers();
  resetSessions();
});

test("signup registers the user and signs them in immediately", async () => {
  const res = await call("POST", "/api/signup", { email: "Grace@example.com", name: "Grace", password: "correct horse" });
  assert.equal(res.status, 201);
  const { token, user } = res.body as { token: string; user: { id: string; email: string; name: string } };
  assert.ok(token);
  assert.equal(user.email, "grace@example.com");
  assert.equal(user.name, "Grace");
  assert.ok(!("passwordHash" in user));
  const me = await call("GET", "/api/me", undefined, token);
  assert.equal(me.status, 200);
  assert.deepEqual(me.body, user);
});

test("signup rejects a duplicate email, bad email, short password and missing fields", async () => {
  const created = await call("POST", "/api/signup", { email: "grace@example.com", name: "Grace", password: "correct horse" });
  assert.equal(created.status, 201);
  const dupe = await call("POST", "/api/signup", { email: "GRACE@example.com", name: "G", password: "correct horse" });
  assert.equal(dupe.status, 400);
  assert.equal((dupe.body as { error: string }).error, "email already registered");
  assert.equal((await call("POST", "/api/signup", { email: "nope", name: "N", password: "correct horse" })).status, 400);
  assert.equal((await call("POST", "/api/signup", { email: "x@example.com", name: "X", password: "short" })).status, 400);
  assert.equal((await call("POST", "/api/signup", { name: "X", password: "correct horse" })).status, 400);
  assert.equal((await call("POST", "/api/signup", { email: "y@example.com", password: "correct horse" })).status, 201);
});

test("signup leaves no usable session when registration fails", async () => {
  assert.equal((await call("POST", "/api/signup", { email: "grace@example.com", name: "G", password: "short" })).status, 400);
  assert.equal((await call("GET", "/api/me")).status, 401);
});

